    private static void _cFft(float[] re, float[] im)
    {
        for (int idx = 0; idx < _brS.Length; idx++)
        {
            var (i, j) = _brS[idx];
            (re[i], re[j]) = (re[j], re[i]);
            (im[i], im[j]) = (im[j], im[i]);
