                int q = p0 + l;
                float tRe = re[q];
                float tIm = im[q];
                re[q] = re[p0] - tRe;
                im[q] = im[p0] - tIm;
                re[p0] += tRe;
                im[p0] += tIm;
                p0 += step;
            }

            for (int k = 1; k < l; k++)
