                    float tIm = curRe * im[q] + curIm * re[q];

                    re[q] = re[p] - tRe;
                    im[q] = im[p] - tIm;
                    re[p] += tRe;
                    im[p] += tIm;
                    p += step;
                }
            }

            l <<= 1;
        }
