    private sealed class _bWr
    {
        private byte[] _buffer;
        private int _byteCount;
        private ulong _bitBuf;
        private int _bitsInBuf;

        public _bWr(int initialCapacity = 256)
        {
            _buffer = new byte[initialCapacity];
